// RFQ subject and body templates (PRD AC-7.2, AC-7.3). Plain text, in the
// broker's own voice: short lines, one greeting, the item list, "let me know
// what you can do." Nothing is generated by a model here.
//
// formatRfqLine() writes one item the way a shop would: the vendor-facing
// designation (canonical when the line is linked, the raw text when custom),
// the sheet size for plate and sheet (the catalog designation PL3/8 names only
// the thickness; the 48x96 the customer asked for lives in dims.w and dims.l),
// quantity and unit, length, grade, then any note in parentheses. Every piece
// is written only when the line has it; nothing is defaulted (AC-2.5).
//
// A custom line is the customer's own words, and those words usually already
// carry the count, the length, and the grade the parser read out of them. A
// part the raw text already states is not written a second time (see
// rawTextCarriesQty, rawTextCarriesLength, rawTextCarriesGrade); a part the
// raw text lacks (a quantity the broker typed on the Review tab) is still
// appended. The raw text itself is never rewritten.

import { format } from "date-fns";
import type { LineUnit } from "@/lib/db/enums";

export type RfqLineView = {
  /** Canonical designation of the linked catalog item, null for a custom line. */
  designation: string | null;
  raw_text: string;
  description: string;
  qty: number | null;
  unit: LineUnit | null;
  length_ft: number | null;
  length_text: string | null;
  grade_spec: string | null;
  /** rfq_lines.note: a per-RFQ note on this line. */
  note: string | null;
  /** request_lines.delivery_notes: what the customer said about this line. */
  delivery_notes: string | null;
  /**
   * request_lines.dims. Only w and l are read, as the sheet size of a plate or
   * sheet line (inches). Optional so callers that have no dims (tests, custom
   * lines) can leave it out.
   */
  dims?: { [key: string]: unknown } | null;
};

const DEFAULT_SUBJECT_NAME = "Material request";

function blankToNull(value: string | null | undefined): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed === "" ? null : trimmed;
}

/** Collapse internal whitespace (a raw line may span several source lines). */
function oneLine(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

/** A quantity as a plain number: 8, 12.5, never 8.0 or an exponent for the sizes a broker sees. */
function formatQty(qty: number): string {
  return Number.isInteger(qty) ? String(qty) : String(Number(qty.toFixed(4)));
}

/**
 * "RFQ: <customer short name or Material request>, <n> items, <MMM d, yyyy>".
 * Singular "1 item". A blank short name counts as none.
 */
export function rfqSubject(args: { customerShortName: string | null; itemCount: number; date: Date }): string {
  const name = blankToNull(args.customerShortName) ?? DEFAULT_SUBJECT_NAME;
  const items = `${args.itemCount} item${args.itemCount === 1 ? "" : "s"}`;
  return `RFQ: ${name}, ${items}, ${format(args.date, "MMM d, yyyy")}`;
}

/**
 * The length part of an item line: "x 50'" when length_ft is a whole number,
 * otherwise "x <length_text>" (with any leading "x" the text already carries
 * removed), otherwise the decimal feet, or nothing.
 */
export function formatRfqLength(line: Pick<RfqLineView, "length_ft" | "length_text">): string | null {
  if (line.length_ft !== null && Number.isInteger(line.length_ft)) return `x ${line.length_ft}'`;
  const text = blankToNull(line.length_text);
  if (text !== null) return `x ${oneLine(text.replace(/^[xX]\s*/, ""))}`;
  if (line.length_ft !== null) return `x ${formatQty(line.length_ft)}'`;
  return null;
}

/** A dims value as a positive number: 48, "48", or "48.5"; anything else is null. */
function dimNumber(value: unknown): number | null {
  const n = typeof value === "number" ? value : typeof value === "string" && value.trim() !== "" ? Number(value) : NaN;
  return Number.isFinite(n) && n > 0 ? n : null;
}

/**
 * The sheet size of a plate or sheet line, "48x96", from dims.w and dims.l
 * (both in inches). Null when either is missing, so a flat bar (w only) or a
 * section (no w or l) writes nothing here.
 */
export function formatSheetSize(dims: RfqLineView["dims"]): string | null {
  if (dims === null || dims === undefined || typeof dims !== "object" || Array.isArray(dims)) return null;
  const w = dimNumber(dims["w"]);
  const l = dimNumber(dims["l"]);
  if (w === null || l === null) return null;
  return `${formatQty(w)}x${formatQty(l)}`;
}

/** Lowercased, whitespace collapsed, curly quotes straightened: the raw text as a containment haystack. */
function foldText(text: string): string {
  return text
    .toLowerCase()
    .replace(/[\u2018\u2019\u2032]/g, "'")
    .replace(/[\u201c\u201d\u2033]/g, '"')
    .replace(/\s+/g, " ")
    .trim();
}

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// Lookarounds are built with new RegExp: a lookbehind in a regex literal needs
// an ES2018 target and this project compiles for ES2017.

/** A number token: not the tail of a fraction, decimal, or size chain ("1/2", "8.5", "4x4x1/4", "3/8 x 6 x 12"). */
const NUMBER_START = "(?<![0-9a-z/.-])(?<!\\bx\\s*)";
const NUMBER_END = "(?![0-9/.])";

/** Words that make the number before them a count. Shape words count only in the plural: "12 plate" is a size, "12 plates" a count. */
const COUNT_WORDS = "pcs?|pieces?|ea|each|lengths|sticks|bars|sheets|plates|angles|tubes|beams|channels|pipes|joints";

/** Words that make the number before them a size, a weight, or a length, never a count. */
const MEASURE_WORDS =
  "in|inch|inches|ft|feet|foot|lf|mm|cm|m|ga|gauge|gage|lb|lbs|cwt|tons?|sq|square|rd|round|rect|rectangular|dia|diameter|od|id|wall|thk|thick|sch|schedule|std|xs|xxs|nps|x|by|long|lg";

/** True when `phrase` occurs in the folded `text` as whole words (no letter or digit touching either end). */
function carriesPhrase(text: string, phrase: string): boolean {
  const needle = foldText(phrase);
  if (needle === "") return false;
  return new RegExp(`(?<![a-z0-9])${escapeRegExp(needle)}(?![a-z0-9])`).test(text);
}

/**
 * Whether the raw text already states the quantity as a count: "qty 10",
 * "quantity: 10", "(4)", "6 pcs" (a count word or the line's own unit), or the
 * text opening with the number and a word that is not a measure ("2 bent
 * plates ..."). A bare number elsewhere ("3/8 x 6 x 12", "8 square 3/8") is a
 * dimension and does not count.
 */
export function rawTextCarriesQty(rawText: string, qty: number, unit: LineUnit | null): boolean {
  const text = foldText(rawText);
  const n = escapeRegExp(formatQty(qty));
  const countWords = unit === null ? COUNT_WORDS : `${COUNT_WORDS}|${escapeRegExp(unit)}`;
  const patterns = [
    `(?:qty|qnty|quantity)\\.?:?\\s*${n}${NUMBER_END}`,
    `\\(\\s*${n}\\s*\\)`,
    `${NUMBER_START}${n}\\s*(?:${countWords})(?![a-z])`,
    `^${n}\\s+(?!(?:${MEASURE_WORDS})(?![a-z]))(?=[a-z(])`,
  ];
  return patterns.some((pattern) => new RegExp(pattern).test(text));
}

/**
 * Whether the raw text already states the length: the length_text itself
 * ("x 40", "480\"", "40' or 48'"), or the whole feet with a feet marker
 * ("40'", "40 ft", "40 feet", "40-0", "40'-0\"").
 */
export function rawTextCarriesLength(rawText: string, line: Pick<RfqLineView, "length_ft" | "length_text">): boolean {
  const text = foldText(rawText);
  const lengthText = blankToNull(line.length_text);
  if (lengthText !== null && carriesPhrase(text, lengthText.replace(/^[xX]\s*/, ""))) return true;
  if (line.length_ft !== null && Number.isInteger(line.length_ft)) {
    const n = escapeRegExp(String(line.length_ft));
    return new RegExp(`${NUMBER_START}${n}\\s*(?:'|ft(?![a-z])|feet(?![a-z])|foot(?![a-z])|lf(?![a-z])|-\\s*0+(?:'|"|(?![0-9])))`).test(text);
  }
  return false;
}

/** Whether the raw text already states the grade ("A36", "A500 Gr B"), as whole words, case-insensitive. */
export function rawTextCarriesGrade(rawText: string, gradeSpec: string | null): boolean {
  const grade = blankToNull(gradeSpec);
  return grade !== null && carriesPhrase(foldText(rawText), grade);
}

/**
 * One item line for the body, for example "8 pcs W12x26 x 50' A992",
 * "40 pcs L2x2x1/4 x 20'", "10 pcs PL3/8 48x96 A36", or
 * "6 pcs C12x30 x 40' (cut to 20')".
 *
 * The sheet size is written only after a canonical designation: a custom line
 * is written as its raw text, which already carries whatever size the customer
 * typed. For the same reason the quantity, length, and grade are appended to a
 * custom line only when its raw text does not already state them: "100 pcs
 * 8x8x5/8 HSS, 40' lengths, A500 Gr B" is written once, and "some angle for
 * clips" with a typed quantity becomes "12 pcs some angle for clips".
 */
export function formatRfqLine(line: RfqLineView): string {
  const designation = blankToNull(line.designation);
  const raw = designation === null ? oneLine(line.raw_text) : null;
  const parts: string[] = [];
  if (line.qty !== null && (raw === null || !rawTextCarriesQty(raw, line.qty, line.unit))) {
    parts.push(line.unit ? `${formatQty(line.qty)} ${line.unit}` : formatQty(line.qty));
  }
  if (designation !== null) {
    parts.push(designation);
    const sheet = formatSheetSize(line.dims);
    if (sheet !== null) parts.push(sheet);
  } else {
    parts.push(raw ?? "");
  }
  const length = formatRfqLength(line);
  if (length !== null && (raw === null || !rawTextCarriesLength(raw, line))) parts.push(length);
  const grade = blankToNull(line.grade_spec);
  if (grade !== null && (raw === null || !rawTextCarriesGrade(raw, grade))) parts.push(grade);
  const notes = [blankToNull(line.note), blankToNull(line.delivery_notes)].filter((n): n is string => n !== null);
  if (notes.length > 0) parts.push(`(${notes.map(oneLine).join("; ")})`);
  return parts.join(" ");
}

/**
 * The body in the broker's voice:
 *
 *   Hi Marcus,
 *   Need pricing and availability on the below, for Lone Star Fabrication.
 *
 *   8 pcs W12x26 x 50' A992
 *   40 pcs L2x2x1/4 x 20'
 *
 *   Delivery: Job site in Waco, liftgate.
 *   Let me know what you can do.
 *
 *   Caleb
 *
 * The customer is named only when includeCustomerName is on and a name is
 * known (AC-7.3). The Delivery line appears only when the request has delivery
 * requirements. Nothing else is written.
 */
export function rfqBody(args: {
  contactFirstName: string | null;
  lines: RfqLineView[];
  customerName: string | null;
  includeCustomerName: boolean;
  deliveryRequirements: string | null;
  senderName: string;
}): string {
  const firstName = blankToNull(args.contactFirstName);
  const customer = args.includeCustomerName ? blankToNull(args.customerName) : null;
  const delivery = blankToNull(args.deliveryRequirements);

  const out: string[] = [];
  out.push(firstName ? `Hi ${firstName},` : "Hi,");
  out.push(`Need pricing and availability on the below${customer ? `, for ${customer}` : ""}.`);
  out.push("");
  for (const line of args.lines) out.push(formatRfqLine(line));
  out.push("");
  if (delivery !== null) out.push(`Delivery: ${oneLine(delivery)}`);
  out.push("Let me know what you can do.");
  out.push("");
  out.push(args.senderName.trim());
  return out.join("\n");
}
